edits.newText:
.kpi-grid,
.table-section,
.volume-section,
footer {
  margin-top: 24px;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.kpi-tile {
  padding: 24px;
  min-height: 158px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.kpi-label {
  color: var(--muted);
  font-size: 0.88rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.kpi-value {
  margin-top: 18px;
  font-size: clamp(2rem, 3.2vw, 3.15rem);
  line-height: 1;
  letter-spacing: -0.05em;
  font-weight: 850;
  color: var(--navy);
}

.kpi-change {
  margin-top: 14px;
  display: inline-flex;
  align-self: flex-start;
  padding: 7px 10px;
  border-radius: 999px;
  font-size: 0.93rem;
  font-weight: 800;
  background: #edf7f2;
  color: var(--green);
}

.kpi-change.warn {
  background: #fff5e6;
  color: var(--amber);
}

